INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES ("boss_tp_down_cut", 4100610, "ＴＰダウンカット", 10061005, "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (3, 4100610, "ＴＰ上昇ダウン", 10061006, "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (9, 4100610, "ＨＰ吸収ダウン", 10061007, "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。");
